"""Build explicit visual negative review notebook."""
import nbformat as nb

b=nb.v4.new_notebook()
md,code=nb.v4.new_markdown_cell,nb.v4.new_code_cell
b.cells=[
    md('# 16.14 - Explicit visual negative review\n\nSelect frontal source-train images from a low seam-score sample, inspect the originals, and record both target states separately. A low computer score never creates a negative label by itself. Ambiguous or partly hidden anterior alignment remains uncertain.'),
    code('from pathlib import Path\nimport hashlib\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom PIL import Image\nfrom IPython.display import display\nroot=Path.cwd().resolve()\nwhile not (root / "AGENTS.md").exists():\n    if root==root.parent: raise RuntimeError("Project root not found")\n    root=root.parent\nbase=root / "data/processed/alignment_omni_frontal_candidates"\nout=root / "docs/reports/alignment/agent_visual_pilot"\nsource=pd.read_csv(base / "review_queue.csv",dtype={"source_image_id":str,"sha256":str}).set_index("source_image_id")\nexcluded=set(pd.read_csv(root / "docs/reports/alignment/omni_frontal_candidate_audit/conservative_train_exclusions.csv",dtype=str).source_image_id)'),
    md('## 1. Record reviewed states\n\nNo visible upper central gap in these five originals. Only two have sufficiently visible and orderly anterior teeth to mark crowding absent; the remaining three are uncertain for crowding. These are agent visual research labels.'),
    code('reviews=pd.DataFrame([\n    ("202401202403121","absent","absent","upper central contact; anterior teeth visible without obvious overlap"),\n    ("202033202012241","absent","absent","upper central contact; anterior teeth visible without obvious overlap"),\n    ("202243202302031","absent","uncertain","upper central contact; lower anterior overlap is ambiguous"),\n    ("202322202302101","absent","uncertain","upper central contact; lower anterior overlap is ambiguous"),\n    ("202346202310161","absent","uncertain","upper central contact; lower anterior teeth are obscured"),\n],columns=["source_image_id","diastema_review","crowding_review","visual_reason"])\nreviews["view_review"]="frontal"\nreviews["reviewer"]="Codex visual review"\nreviews["review_state"]="agent_visual_provisional"\nfor r in reviews.itertuples():\n    s=source.loc[r.source_image_id]\n    assert s["split"]=="train" and r.source_image_id not in excluded\n    assert hashlib.sha256((root / s["image_path"]).read_bytes()).hexdigest()==s["sha256"]\ndisplay(reviews)'),
    md('## 2. Show the reviewed negatives\n\nA negative image contributes an empty YOLO label only after both target statuses are explicitly absent. Images with an uncertain crowding status cannot become whole-image negatives.'),
    code('fig,axes=plt.subplots(3,2,figsize=(12,11))\nfor ax,r in zip(axes.flat,reviews.itertuples()):\n    ax.imshow(Image.open(root / source.loc[r.source_image_id,"image_path"]))\n    ax.set_title(f"{r.source_image_id}: gap {r.diastema_review}, crowding {r.crowding_review}")\n    ax.axis("off")\nfor ax in list(axes.flat)[len(reviews):]: ax.axis("off")\nfig.tight_layout()\nfig.savefig(out / "negative_review_batch.png",dpi=150)\nplt.show(); plt.close(fig)'),
    md('## 3. Save visual review provenance\n\nThe output stays separate from OMNI source annotations. It must not be interpreted as dentist-reviewed ground truth or phone-photo specificity.'),
    code('path=out / "negative_review_states.csv"\nif path.exists(): assert pd.read_csv(path,dtype={"source_image_id":str}).equals(reviews),f"Existing review differs: {path}"\nelse: reviews.to_csv(path,index=False)\nprint("Saved",path)\nprint("Two-target visual negatives:",sum((reviews.diastema_review=="absent") & (reviews.crowding_review=="absent")))'),
]
b.metadata.kernelspec={'display_name':'DentalSelfie','language':'python','name':'dentalselfie-local'}
nb.write(b,'notebooks/alignment/16_14_visual_negative_review.ipynb')
